import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { motion } from 'framer-motion';
import SafeIcon from '../common/SafeIcon';
import { tours } from '../data/mockData';
import { businessPartners, offers } from '../data/localMarketplace';
import { getStorageKey, readLocalEvents, readPendingApiEvents, syncPendingApiEvents } from '../utils/localEvents';
import { clearDemoEvidenceForTours, seedDemoEvidenceForTours } from '../utils/demoEvidence';

function readJson(key, fallback) {
  try {
    return JSON.parse(localStorage.getItem(key) || JSON.stringify(fallback));
  } catch {
    return fallback;
  }
}

function buildTourSummary(tour) {
  const events = readLocalEvents().filter(event => event.payload?.tourId === tour.id);
  const visitedStops = readJson(getStorageKey('progress', tour.id), []);
  const savedStops = readJson(getStorageKey('saved-stops', tour.id), []);
  const activatedOffers = readJson(getStorageKey('offers', tour.id), []);
  const loyaltyStamps = readJson(getStorageKey('loyalty', tour.id), {});
  const currentStopIndex = Number(localStorage.getItem(getStorageKey('current-stop-index', tour.id)) || 0);
  const currentStop = tour.stops?.[currentStopIndex] || null;
  const usefulSignals = events.filter(event => event.type === 'field_signal' && event.payload?.signal === 'useful').length;
  const riskySignals = events.filter(event => event.type === 'field_signal' && ['spammy', 'confusing'].includes(event.payload?.signal)).length;
  const offerImpressions = events.filter(event => event.type === 'offer_impression').length;

  return {
    tour,
    events,
    visitedStops,
    savedStops,
    activatedOffers,
    currentStopIndex,
    currentStop,
    loyaltyStampCount: Object.values(loyaltyStamps).reduce((sum, count) => sum + Number(count || 0), 0),
    usefulSignals,
    riskySignals,
    offerImpressions,
    fieldReadiness: tour.stops?.length ? Math.round((visitedStops.length / tour.stops.length) * 100) : 0
  };
}

function fallbackCopyText(text) {
  const textarea = document.createElement('textarea');
  textarea.value = text;
  textarea.setAttribute('readonly', '');
  textarea.style.position = 'fixed';
  textarea.style.left = '-9999px';
  document.body.appendChild(textarea);
  textarea.select();

  try {
    const copied = document.execCommand('copy');
    return copied;
  } finally {
    textarea.remove();
  }
}

export default function B2BDashboard() {
  const navigate = useNavigate();
  const [refreshKey, setRefreshKey] = useState(0);
  const [syncStatus, setSyncStatus] = useState('');
  const [exportStatus, setExportStatus] = useState('');
  const [summaryPreview, setSummaryPreview] = useState('');
  const fieldTours = tours.filter(tour => tour.stops?.length);
  const summaries = fieldTours.map(buildTourSummary);
  const allEvents = readLocalEvents();
  const pendingApiEvents = readPendingApiEvents();
  const totalStops = summaries.reduce((sum, summary) => sum + summary.visitedStops.length, 0);
  const totalStarts = allEvents.filter(event => ['narration_played', 'maps_opened', 'stop_completed'].includes(event.type)).length;
  const totalOfferActions = summaries.reduce((sum, summary) => sum + summary.activatedOffers.length + summary.offerImpressions, 0);
  const totalUsefulSignals = summaries.reduce((sum, summary) => sum + summary.usefulSignals, 0);
  const partnerSlots = businessPartners.length;
  const activeOfferCount = offers.length;
  const lastEvent = allEvents[0];
  const merchantSummaries = businessPartners.map(business => {
    const merchantEvents = allEvents.filter(event => event.payload?.businessId === business.id);
    return {
      ...business,
      localEvents: merchantEvents.length,
      activatedOffers: merchantEvents.filter(event => event.type === 'offer_activate').length,
      loyaltyStamps: merchantEvents.filter(event => event.type === 'loyalty_stamp_granted').length,
      usefulSignals: merchantEvents.filter(event => event.type === 'field_signal' && event.payload?.signal === 'useful').length,
      frictionSignals: merchantEvents.filter(event => event.type === 'field_signal' && ['spammy', 'confusing'].includes(event.payload?.signal)).length
    };
  });

  const buildPartnerSummary = () => ({
    generatedAt: new Date().toISOString(),
    scope: 'local-static-preview',
    totals: {
      localEvents: allEvents.length,
      tourActions: totalStarts,
      stopsCompleted: totalStops,
      offerSignals: totalOfferActions,
      usefulSignals: totalUsefulSignals,
      queuedApiEvents: pendingApiEvents.length,
      merchantSlots: partnerSlots,
      demoOffers: activeOfferCount
    },
    latestEvent: lastEvent || null,
    tours: summaries.map(summary => ({
      tourId: summary.tour.id,
      title: summary.tour.title,
      city: summary.tour.city,
      status: summary.tour.status || 'field-test pack',
      fieldReadiness: summary.fieldReadiness,
      currentStopPosition: summary.currentStop ? summary.currentStopIndex + 1 : null,
      currentStopId: summary.currentStop?.id || null,
      currentStopTitle: summary.currentStop?.title || null,
      currentSourceStopNumber: summary.currentStop?.number || null,
      visitedStops: summary.visitedStops.length,
      savedStops: summary.savedStops.length,
      activatedOffers: summary.activatedOffers.length,
      loyaltyStamps: summary.loyaltyStampCount,
      usefulSignals: summary.usefulSignals,
      riskySignals: summary.riskySignals,
      offerImpressions: summary.offerImpressions,
      localEvents: summary.events.length
    })),
    merchants: merchantSummaries.map(business => ({
      id: business.id,
      name: business.name,
      category: business.category,
      neighborhood: business.neighborhood,
      relatedTourIds: business.relatedTourIds,
      relatedStopIds: business.relatedStopIds,
      storyRelevance: business.storyRelevance,
      localEvents: business.localEvents,
      activatedOffers: business.activatedOffers,
      loyaltyStamps: business.loyaltyStamps,
      usefulSignals: business.usefulSignals,
      frictionSignals: business.frictionSignals
    })),
    boundaries: [
      'Field-test console, not a production merchant portal',
      'Static/local preview only',
      'Browser-local synthetic evidence',
      'No live merchant integration',
      'No redemption verification or payment handling',
      'No production backend dependency'
    ]
  });

  const retryPendingEvents = async () => {
    setSyncStatus('Retrying local queue…');
    const results = await syncPendingApiEvents();
    const syncedCount = results.filter(result => result.ok).length;
    const failedCount = results.length - syncedCount;
    setRefreshKey(key => key + 1);
    setSyncStatus(results.length ? `${syncedCount} synced · ${failedCount} still queued` : 'No queued events');
    window.setTimeout(() => setSyncStatus(''), 3000);
  };

  const copyPartnerSummary = async () => {
    const summary = JSON.stringify(buildPartnerSummary(), null, 2);
    setSummaryPreview(summary);

    try {
      if (navigator.clipboard?.writeText) {
        await Promise.race([
          navigator.clipboard.writeText(summary),
          new Promise((_, reject) => window.setTimeout(() => reject(new Error('Clipboard timed out')), 1000))
        ]);
        setExportStatus('Partner summary copied');
      } else if (fallbackCopyText(summary)) {
        setExportStatus('Partner summary copied');
      } else {
        setExportStatus('Copy unavailable — use download');
      }
    } catch {
      setExportStatus(fallbackCopyText(summary) ? 'Partner summary copied' : 'Copy unavailable — use download');
    }
    window.setTimeout(() => setExportStatus(''), 3000);
  };

  const downloadPartnerSummary = () => {
    const summary = JSON.stringify(buildPartnerSummary(), null, 2);
    setSummaryPreview(summary);
    const blob = new Blob([summary], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `tour-engine-partner-summary-${new Date().toISOString().slice(0, 10)}.json`;
    document.body.appendChild(link);
    link.click();
    link.remove();
    URL.revokeObjectURL(url);
    setExportStatus('Partner summary downloaded');
    window.setTimeout(() => setExportStatus(''), 3000);
  };

  const seedPartnerDemo = () => {
    const seededTours = seedDemoEvidenceForTours(fieldTours);
    setRefreshKey(key => key + 1);
    setSummaryPreview(JSON.stringify({ seededAt: new Date().toISOString(), seededTours }, null, 2));
    setExportStatus(`Seeded ${seededTours.length} tour evidence packs`);
    window.setTimeout(() => setExportStatus(''), 3000);
  };

  const resetPartnerDemo = () => {
    const result = clearDemoEvidenceForTours(fieldTours);
    setRefreshKey(key => key + 1);
    setSummaryPreview(JSON.stringify({ resetAt: new Date().toISOString(), ...result }, null, 2));
    setExportStatus(`Reset ${result.clearedTours.length} tour evidence packs`);
    window.setTimeout(() => setExportStatus(''), 3000);
  };

  return (
    <motion.div 
      initial={{ opacity: 0 }} 
      animate={{ opacity: 1 }} 
      className="min-h-screen bg-slate-900 text-slate-300 pb-20"
      data-refresh-key={refreshKey}
    >
      <header className="px-5 py-6 border-b border-slate-800 flex items-center justify-between sticky top-0 bg-slate-900/90 backdrop-blur z-10">
        <div className="flex items-center gap-3">
          <button onClick={() => navigate('/')} className="p-2 -ml-2 rounded-full hover:bg-slate-800 text-slate-400">
            <SafeIcon name="ArrowLeft" className="w-5 h-5" />
          </button>
          <div>
            <h1 className="text-lg font-bold text-white">Field-test Console</h1>
            <p className="text-xs text-slate-500">Partner evidence preview · local/demo only</p>
          </div>
        </div>
        <div className="w-8 h-8 bg-slate-800 rounded flex items-center justify-center font-bold text-white text-xs border border-slate-700">
          VP
        </div>
      </header>

      <div className="p-5 space-y-6">
        <div className="bg-gradient-to-br from-slate-800 to-slate-900 border border-slate-700 rounded-2xl p-6 shadow-lg">
          <h2 className="text-white text-xl font-bold mb-2" style={{ fontFamily: 'Georgia, serif' }}>
            Prove local intent before backend spend.
          </h2>
          <p className="text-sm text-slate-400 mb-6">
            Static PWA preview reading browser-local progress, route-position, offer, loyalty, and field-test events from the tour player. This is not a live merchant portal, redemption system, or production analytics dashboard.
          </p>
          
          <button onClick={() => navigate('/player/osaka-camera-crawl')} className="w-full bg-orange-600 hover:bg-orange-500 text-white font-bold py-3 px-4 rounded-xl shadow-md transition-colors flex items-center justify-center gap-2">
            <SafeIcon name="PlayCircle" className="w-5 h-5" />
            Continue camera crawl field test
          </button>

          <div className="mt-3 grid grid-cols-2 gap-2">
            <button onClick={seedPartnerDemo} className="rounded-xl bg-orange-500 px-3 py-2 text-xs font-bold uppercase tracking-widest text-slate-950 active:scale-95">
              Seed demo
            </button>
            <button onClick={resetPartnerDemo} className="rounded-xl bg-slate-800 px-3 py-2 text-xs font-bold uppercase tracking-widest text-slate-200 ring-1 ring-slate-700 active:scale-95">
              Reset demo
            </button>
            <button onClick={copyPartnerSummary} className="rounded-xl bg-slate-700 px-3 py-2 text-xs font-bold uppercase tracking-widest text-slate-100 active:scale-95">
              Copy summary
            </button>
            <button onClick={downloadPartnerSummary} className="rounded-xl bg-slate-950 px-3 py-2 text-xs font-bold uppercase tracking-widest text-slate-100 ring-1 ring-slate-700 active:scale-95">
              Download JSON
            </button>
          </div>
          {exportStatus && (
            <div className="mt-3 rounded-xl bg-slate-950/80 px-3 py-2 text-xs font-semibold text-slate-200">
              {exportStatus}
            </div>
          )}
          {summaryPreview && (
            <div className="mt-3 rounded-xl border border-slate-700 bg-slate-950/80 p-3">
              <div className="mb-2 flex items-center justify-between gap-3">
                <p className="text-[10px] font-bold uppercase tracking-widest text-slate-400">Latest summary payload</p>
                <button onClick={() => setSummaryPreview('')} className="text-[10px] font-bold uppercase tracking-widest text-slate-500">Hide</button>
              </div>
              <pre className="max-h-36 overflow-auto whitespace-pre-wrap text-[10px] leading-relaxed text-slate-300">{summaryPreview}</pre>
            </div>
          )}
        </div>

        <div>
          <h3 className="text-xs font-bold uppercase tracking-widest text-slate-500 mb-4">Local field evidence</h3>
          <div className="grid grid-cols-2 gap-4">
            <div className="bg-slate-800 border border-slate-700 rounded-xl p-4">
              <SafeIcon name="Eye" className="w-5 h-5 text-blue-400 mb-2" />
              <p className="text-2xl font-bold text-white">{allEvents.length}</p>
              <p className="text-xs text-slate-400">Local Events</p>
            </div>
            <div className="bg-slate-800 border border-slate-700 rounded-xl p-4">
              <SafeIcon name="PlayCircle" className="w-5 h-5 text-emerald-400 mb-2" />
              <p className="text-2xl font-bold text-white">{totalStarts}</p>
              <p className="text-xs text-slate-400">Tour Actions</p>
            </div>
            <div className="bg-slate-800 border border-slate-700 rounded-xl p-4">
              <SafeIcon name="CheckCircle" className="w-5 h-5 text-purple-400 mb-2" />
              <p className="text-2xl font-bold text-white">{totalStops}</p>
              <p className="text-xs text-slate-400">Stops Completed</p>
            </div>
            <div className="bg-slate-800 border border-slate-700 rounded-xl p-4">
              <SafeIcon name="TrendingUp" className="w-5 h-5 text-orange-400 mb-2" />
              <p className="text-2xl font-bold text-white">{totalOfferActions}</p>
              <p className="text-xs text-slate-400">Offer Signals</p>
            </div>
          </div>
        </div>

        <div className="bg-slate-800 border border-slate-700 rounded-2xl p-4">
          <div className="flex items-start justify-between gap-3">
            <div>
              <h3 className="text-sm font-bold text-white">Boundary / API fallback</h3>
              <p className="text-xs text-slate-400 mt-1">Field-test console only. Events queue locally when the optional dev API is not running; no live merchant verification, redemption, payment, or production analytics.</p>
            </div>
            <div className="flex flex-col items-end gap-2">
              <span className={`rounded-full px-2 py-1 text-[10px] font-bold uppercase ${pendingApiEvents.length ? 'bg-amber-500/15 text-amber-300' : 'bg-emerald-500/15 text-emerald-300'}`}>
                {pendingApiEvents.length ? `${pendingApiEvents.length} queued` : 'local only'}
              </span>
              {pendingApiEvents.length > 0 && (
                <button onClick={retryPendingEvents} className="rounded-full bg-slate-900 px-3 py-1 text-[10px] font-bold uppercase text-slate-300 ring-1 ring-slate-700 active:scale-95">
                  Retry sync
                </button>
              )}
            </div>
          </div>
          {syncStatus && (
            <div className="mt-3 rounded-xl bg-slate-900/70 px-3 py-2 text-xs font-semibold text-slate-300">
              {syncStatus}
            </div>
          )}
          <div className="mt-4 grid grid-cols-2 gap-3 text-xs">
            <div className="rounded-xl bg-slate-900/70 p-3">
              <p className="text-lg font-black text-white">{partnerSlots}</p>
              <p className="text-slate-500">merchant slots</p>
            </div>
            <div className="rounded-xl bg-slate-900/70 p-3">
              <p className="text-lg font-black text-white">{activeOfferCount}</p>
              <p className="text-slate-500">demo offers</p>
            </div>
            <div className="rounded-xl bg-slate-900/70 p-3">
              <p className="text-lg font-black text-white">{totalUsefulSignals}</p>
              <p className="text-slate-500">useful taps</p>
            </div>
            <div className="rounded-xl bg-slate-900/70 p-3">
              <p className="text-lg font-black text-white">{lastEvent ? new Date(lastEvent.createdAt).toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' }) : '—'}</p>
              <p className="text-slate-500">latest signal</p>
            </div>
          </div>
        </div>

        <div>
          <h3 className="text-xs font-bold uppercase tracking-widest text-slate-500 mb-4">Active Field-test Packs</h3>
          <div className="space-y-3">
            {summaries.map((summary) => (
              <button key={summary.tour.id} onClick={() => navigate(`/evidence/${summary.tour.id}`)} className="w-full text-left bg-slate-800 border border-slate-700 p-4 rounded-xl active:scale-[0.99] transition-transform">
                <div className="flex items-center justify-between gap-3">
                  <div className="min-w-0">
                    <p className="font-bold text-white text-sm truncate">{summary.tour.title}</p>
                    <p className="text-xs text-slate-400 mt-0.5">{summary.tour.city} • {summary.tour.status || 'field-test pack'}</p>
                    {summary.currentStop && <p className="text-[10px] text-slate-500 mt-1">Current route position {summary.currentStopIndex + 1} · source stop {summary.currentStop.number} · {summary.currentStop.title}</p>}
                  </div>
                  <SafeIcon name="ChevronRight" className="w-5 h-5 text-slate-500 flex-shrink-0" />
                </div>
                <div className="mt-3 grid grid-cols-4 gap-2 text-center">
                  <div className="rounded-lg bg-slate-900/70 py-2">
                    <p className="text-sm font-black text-white">{summary.fieldReadiness}%</p>
                    <p className="text-[9px] uppercase tracking-widest text-slate-500">walked</p>
                  </div>
                  <div className="rounded-lg bg-slate-900/70 py-2">
                    <p className="text-sm font-black text-white">{summary.activatedOffers.length}</p>
                    <p className="text-[9px] uppercase tracking-widest text-slate-500">offers</p>
                  </div>
                  <div className="rounded-lg bg-slate-900/70 py-2">
                    <p className="text-sm font-black text-white">{summary.loyaltyStampCount}</p>
                    <p className="text-[9px] uppercase tracking-widest text-slate-500">stamps</p>
                  </div>
                  <div className="rounded-lg bg-slate-900/70 py-2">
                    <p className={`text-sm font-black ${summary.riskySignals ? 'text-amber-300' : 'text-white'}`}>{summary.riskySignals}</p>
                    <p className="text-[9px] uppercase tracking-widest text-slate-500">friction</p>
                  </div>
                </div>
              </button>
            ))}
          </div>
        </div>

        <div>
          <h3 className="text-xs font-bold uppercase tracking-widest text-slate-500 mb-4">Demo merchant relevance map</h3>
          <div className="space-y-3">
            {merchantSummaries.map((business) => (
              <div key={business.id} className="bg-slate-800 border border-slate-700 p-4 rounded-xl">
                <div>
                  <p className="font-bold text-white text-sm">{business.name}</p>
                  <p className="text-xs text-slate-400 mt-0.5">{business.category} • {business.distanceLabel}</p>
                  <p className="text-xs text-slate-500 mt-2 leading-relaxed">{business.storyRelevance}</p>
                  <div className="mt-3 grid grid-cols-4 gap-1.5 text-center">
                    <div className="rounded-lg bg-slate-900/70 py-2">
                      <p className="text-sm font-black text-white">{business.activatedOffers}</p>
                      <p className="text-[8px] uppercase tracking-widest text-slate-500">offers</p>
                    </div>
                    <div className="rounded-lg bg-slate-900/70 py-2">
                      <p className="text-sm font-black text-white">{business.loyaltyStamps}</p>
                      <p className="text-[8px] uppercase tracking-widest text-slate-500">stamps</p>
                    </div>
                    <div className="rounded-lg bg-slate-900/70 py-2">
                      <p className="text-sm font-black text-white">{business.usefulSignals}</p>
                      <p className="text-[8px] uppercase tracking-widest text-slate-500">useful</p>
                    </div>
                    <div className="rounded-lg bg-slate-900/70 py-2">
                      <p className={`text-sm font-black ${business.frictionSignals ? 'text-amber-300' : 'text-white'}`}>{business.frictionSignals}</p>
                      <p className="text-[8px] uppercase tracking-widest text-slate-500">friction</p>
                    </div>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </motion.div>
  );
}
